/**
 * Hand-written companion to worker-configuration.d.ts (generated by
 * `wrangler types`). Holds the declarations generation cannot produce:
 * the OpenNext build artifact, worker secrets (which never appear in
 * wrangler.jsonc), and our own bindings on OpenNext's CloudflareEnv.
 *
 * Deliberately a script (no imports/exports): top-level declarations in a
 * script file are global, and the ambient module below matches the bare
 * import in custom-worker.ts.
 */

// Resolved by wrangler's `alias` config to .open-next/worker.js at bundle
// time; declared here so custom-worker.ts type-checks before the first build.
declare module "opennext-worker" {
  const handler: {
    fetch(
      request: Request,
      env: Env,
      ctx: ExecutionContext,
    ): Promise<Response> | Response;
  };
  export default handler;
}

// Worker secrets live outside wrangler.jsonc, so `wrangler types` never
// generates them.
interface Env {
  CRON_SECRET?: string;
}

// OpenNext's own env interface, merged here with our receipt bucket.
interface CloudflareEnv {
  RECEIPTS?: R2Bucket;
}
